from pathlib import Path
import csv
import json
import cv2

root = Path('test-output/30c5215_五项目回归_13普通图_4VISIA图')
datasets = {'普通13': 13, 'VISIA4': 4}
requirements = {
    '红区': ['03_RBX红区结果图.jpg', '06_VISIA红色区实例图.jpg', '红区量化指标.csv', '红区量化指标.json'],
    '斑点': ['01_Spots斑点结果图.jpg', '02_Spots量化指标.csv', '02_Spots量化指标.json'],
    '棕区': ['01_RBX棕区结果图.jpg', '02_VISIA棕色斑实例图.jpg', '棕色斑量化指标.csv', '棕色斑量化指标.json'],
    '纹理': ['01_纹理检测结果图.jpg', '纹理量化指标.csv', '纹理量化指标.json'],
    '毛孔': ['01_毛孔检测结果图.jpg', '毛孔量化指标.csv', '毛孔量化指标.json'],
}
errors=[]
for dataset, expected_count in datasets.items():
    for project, names in requirements.items():
        base = root/dataset/project
        dirs = sorted(p for p in base.iterdir() if p.is_dir()) if base.is_dir() else []
        if len(dirs) != expected_count:
            errors.append(f'{dataset}/{project}: 子目录 {len(dirs)} != {expected_count}')
        for sample in dirs:
            for name in names:
                path=sample/name
                if not path.is_file() or path.stat().st_size == 0:
                    errors.append(f'缺失或空文件: {path}')
                    continue
                if path.suffix.lower() in {'.jpg','.jpeg','.png'} and cv2.imread(str(path)) is None:
                    errors.append(f'无法解码: {path}')
                if path.suffix == '.json':
                    json.loads(path.read_text(encoding='utf-8'))
                if path.suffix == '.csv':
                    with path.open(encoding='utf-8-sig', newline='') as f:
                        rows=list(csv.reader(f))
                    if len(rows)!=2 or len(rows[0])!=len(rows[1]):
                        errors.append(f'CSV格式不正确: {path}')
print(json.dumps({'errors': errors, 'status': 'PASS' if not errors else 'FAIL'}, ensure_ascii=False, indent=2))
